g=[[1]*12 for _ in range(29)]
for r,c in [(19,2),(19,3),(19,5),(19,6),(19,7),(20,2),(20,7),(21,7),(22,2),(22,7),(23,2),(23,7),(24,2),(24,7),(25,4),(25,5),(25,6),(25,7)]:g[r][c]=4
# fill only 1-colored gaps between consecutive 4s in each row/column
orig=[row[:] for row in g]
for r in range(29):
 cs=[c for c in range(12) if orig[r][c]==4]
 for a,b in zip(cs,cs[1:]):
  for c in range(a+1,b):
   if orig[r][c]==1:g[r][c]=2
for c in range(12):
 rs=[r for r in range(29) if orig[r][c]==4]
 for a,b in zip(rs,rs[1:]):
  for r in range(a+1,b):
   if orig[r][c]==1:g[r][c]=2
import json
assert len(g)==29 and all(len(row)==12 for row in g)
print(json.dumps({'action':'submit','grid':g},separators=(',',':')))

